type Socket = tungstenite::WebSocket<tungstenite::stream::MaybeTlsStream<TcpStream>>;

fn dial(
    target: &url::Url,
    deadline: Instant,
    hook: &impl Fn(&mut tungstenite::http::HeaderMap) -> Result<(), Error>,
) -> Result<Socket, Error> {
    let host = target
        .host_str()
        .ok_or_else(|| Error::new("invalid_url", "missing host"))?;
    let port = target
        .port_or_known_default()
        .ok_or_else(|| Error::new("invalid_url", "missing port"))?;
    let mut last_error = Error::new("connection_closed", "no server addresses");
    for address in (host, port)
        .to_socket_addrs()
        .map_err(|e| Error::new("connection_closed", e.to_string()))?
    {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            break;
        }
        // Each socket handshake starts with its own WebSocket headers. The hook
        // adds to them rather than replacing Host, Upgrade or Sec-WebSocket-Key.
        let mut request = target
            .as_str()
            .into_client_request()
            .map_err(|e| Error::new("invalid_url", e.to_string()))?;
        catch_unwind(AssertUnwindSafe(|| hook(request.headers_mut())))
            .map_err(|_| Error::new("callback_panic", "header hook panicked"))??;
        match TcpStream::connect_timeout(&address, remaining.min(Duration::from_secs(1))) {
            Ok(stream) => {
                let _ = stream.set_read_timeout(Some(remaining.min(Duration::from_secs(1))));
                let _ = stream.set_write_timeout(Some(remaining.min(Duration::from_secs(1))));
                match tungstenite::client_tls_with_config(request, stream, None, None) {
                    Ok((mut ws, _)) => {
                        let socket = match ws.get_mut() {
                            tungstenite::stream::MaybeTlsStream::Plain(socket) => socket,
                            tungstenite::stream::MaybeTlsStream::Rustls(tls) => &mut tls.sock,
                            _ => {
                                return Err(Error::new(
                                    "unsupported_tls_stream",
                                    "unsupported WebSocket stream type",
                                ))
                            }
                        };
                        socket
                            .set_read_timeout(Some(Duration::from_millis(100)))
                            .map_err(|e| Error::new("connection_closed", e.to_string()))?;
                        return Ok(ws);
                    }
                    Err(e) => last_error = Error::new("connection_closed", e.to_string()),
                }
            }
            Err(e) => last_error = Error::new("connection_closed", e.to_string()),
        }
    }
    Err(last_error)
}
fn callback<F: FnOnce()>(f: F) -> Result<(), Error> {
    catch_unwind(AssertUnwindSafe(f))
        .map_err(|_| Error::new("callback_panic", "connection callback panicked"))
}
