    #[test]
    fn transport_reconnect_and_queued_calls() {
        use std::net::TcpListener;
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().unwrap();
            let mut ws = tungstenite::accept(stream).unwrap();
            let first = ws.read().unwrap().into_data();
            assert_eq!(Envelope::decode(&first).unwrap().method, "first");
            drop(ws);
            let (stream, _) = listener.accept().unwrap();
            let mut ws = tungstenite::accept(stream).unwrap();
            let second = Envelope::decode(&ws.read().unwrap().into_data()).unwrap();
            assert_eq!(second.method, "second");
            let mut response = Envelope::new(FrameType::Response);
            response.id = second.id;
            response.payload = vec![42];
            ws.send(tungstenite::Message::Binary(response.encode().unwrap()))
                .unwrap();
        });
        let (state_tx, state_rx) = mpsc::channel();
        let transport = Transport::connect(
            &format!("ws://{address}/"),
            "1",
            |_| {},
            move |state| {
                let _ = state_tx.send(state);
            },
        )
        .unwrap();
        assert_eq!(
            state_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
            ConnectionState::Connecting
        );
        assert_eq!(
            state_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
            ConnectionState::Connected
        );
        assert_eq!(
            transport.call("first", vec![]).unwrap_err().code,
            "connection_closed"
        );
        assert_eq!(transport.call("second", vec![]).unwrap(), vec![42]);
        transport.close();
        server.join().unwrap();
    }
    fn send(ws: &mut tungstenite::WebSocket<std::net::TcpStream>, env: Envelope) {
        ws.send(tungstenite::Message::Binary(env.encode().unwrap()))
            .unwrap();
    }
    #[test]
    fn early_event_version_query_and_state() {
        use std::net::TcpListener;
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let (query_tx, query_rx) = mpsc::channel();
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().unwrap();
            let mut ws = tungstenite::accept_hdr(
                stream,
                |request: &tungstenite::handshake::server::Request,
                 response: tungstenite::handshake::server::Response| {
                    query_tx
                        .send(request.uri().query().unwrap().to_string())
                        .unwrap();
                    Ok(response)
                },
            )
            .unwrap();
            let mut event = Envelope::new(FrameType::Event);
            event.payload = vec![7];
            send(&mut ws, event);
            ws.read().unwrap(); // keep socket alive until close
        });
        let (events_tx, events_rx) = mpsc::channel();
        let (state_tx, state_rx) = mpsc::channel();
        let client = Transport::connect(
            &format!("ws://{address}/path?x=hello+world&version=old#part"),
            "v 2",
            move |bytes| {
                events_tx.send(bytes).unwrap();
            },
            move |state| {
                state_tx.send(state).unwrap();
            },
        )
        .unwrap();
        let query = query_rx.recv_timeout(Duration::from_secs(2)).unwrap();
        let pairs: Vec<_> = url::form_urlencoded::parse(query.as_bytes()).collect();
        assert_eq!(pairs.iter().filter(|(k, _)| k == "version").count(), 1);
        assert!(pairs.iter().any(|(k, v)| k == "version" && v == "v 2"));
        assert!(pairs.iter().any(|(k, v)| k == "x" && v == "hello world"));
        assert_eq!(
            events_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
            vec![7]
        );
        assert_eq!(
            state_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
            ConnectionState::Connecting
        );
        assert_eq!(
            state_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
            ConnectionState::Connected
        );
        client.close();
        assert_eq!(
            client.call("later", vec![]).unwrap_err().code,
            "connection_closed"
        );
        server.join().unwrap();
    }
    #[test]
    fn setup_connection_error_and_malformed_frame() {
        use std::net::TcpListener;
        for malformed in [false, true] {
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            let addr = listener.local_addr().unwrap();
            let server = thread::spawn(move || {
                let (stream, _) = listener.accept().unwrap();
                let mut ws = tungstenite::accept(stream).unwrap();
                if malformed {
                    ws.send(tungstenite::Message::Binary(vec![99])).unwrap();
                } else {
                    let mut env = Envelope::new(FrameType::ConnectionError);
                    env.error_code = "version_mismatch".into();
                    env.error = "wrong version".into();
                    send(&mut ws, env);
                }
            });
            let err = match Transport::connect_with_timeout(
                &format!("ws://{addr}"),
                "v",
                Duration::from_secs(2),
                |_| {},
                |_| {},
            ) {
                Ok(client) => {
                    client.close();
                    panic!("setup error reported as connected")
                }
                Err(e) => e,
            };
            assert_eq!(
                err.code,
                if malformed {
                    "malformed"
                } else {
                    "version_mismatch"
                }
            );
            server.join().unwrap();
        }
    }
    #[test]
    fn correlation_wire_error_and_callback_panic_fail_pending() {
        use std::net::TcpListener;
        use std::sync::Arc;
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().unwrap();
            let mut ws = tungstenite::accept(stream).unwrap();
            let a = Envelope::decode(&ws.read().unwrap().into_data()).unwrap();
            let b = Envelope::decode(&ws.read().unwrap().into_data()).unwrap();
            let mut error = Envelope::new(FrameType::Error);
            error.id = b.id;
            error.error_code = "denied".into();
            error.error = "no".into();
            send(&mut ws, error);
            let mut response = Envelope::new(FrameType::Response);
            response.id = a.id;
            response.payload = a.method.as_bytes().to_vec();
            send(&mut ws, response);
            let pending = Envelope::decode(&ws.read().unwrap().into_data()).unwrap();
            assert_eq!(pending.method, "pending");
            let mut event = Envelope::new(FrameType::Event);
            event.payload = vec![1];
            send(&mut ws, event);
        });
        let client = Arc::new(
            Transport::connect(
                &format!("ws://{addr}"),
                "v",
                |_| panic!("bad handler"),
                |_| panic!("bad state handler"),
            )
            .unwrap(),
        );
        let a = Arc::clone(&client);
        let first = thread::spawn(move || a.call("first", vec![]));
        let b = Arc::clone(&client);
        let second = thread::spawn(move || b.call("second", vec![]));
        let first = first.join().unwrap();
        let second = second.join().unwrap();
        let outcomes = [first, second];
        assert!(outcomes
            .iter()
            .any(|x| x.as_ref().ok() == Some(&b"first".to_vec())
                || x.as_ref().ok() == Some(&b"second".to_vec())));
        assert!(outcomes
            .iter()
            .any(|x| x.as_ref().err().map(|e| e.code.as_str()) == Some("denied")));
        assert_eq!(
            client.call("pending", vec![]).unwrap_err().code,
            "callback_panic"
        );
        client.close();
        server.join().unwrap();
    }
